function pickComment(pool,profile){profile.commentHistory||=[];const fresh=pool.filter(c=>!profile.commentHistory.includes(c));const chosen=rand(fresh.length?fresh:pool);profile.commentHistory.push(chosen);if(profile.commentHistory.length>12)profile.commentHistory.shift();return chosen}
function pickSticker(profile,special=false){const pool=special?STICKERS.filter(s=>s.includes('👑')||s.includes('💎')||s.includes('✨')):STICKERS;const owned=new Set(profile.stickers.map(s=>s.sticker));const fresh=pool.filter(s=>!owned.has(s));return rand(fresh.length?fresh:pool)}
