function applySettings(){const p=person();if(!p)return;document.body.classList.toggle('large-text',!!p.settings.largeText);document.body.classList.toggle('reduced-motion',!!p.settings.reducedMotion)}

const app=document.querySelector('#app');
let vocab=[], db={version:1,profiles:[],activeId:null}, screen='start', game=null, selectedAvatar=AVATARS[0], selectedGrade=2, feedback=null, sequence=[], composing='', wrongChoice='', banner='';
const storeKey='english-adventure-state-v1';
