function header(){const p=person();return `<header class="topbar"><div class="logo" data-action="home"><div class="logo-icon">🦄</div><div><strong>English Adventure</strong><small>✨ MISJA 25 · NAUKA PRZEZ ZABAWĘ · v${APP_VERSION}</small></div></div><nav class="nav"><button data-action="home">🏠 Krainy</button><button data-action="rank">🏆 Ranking</button><button data-action="album">🎁 Album</button><button data-action="parent">⚙️ Rodzic</button>${p?`<button data-action="profiles">${esc(p.avatar)} ${esc(p.name)} ▾</button>`:''}</nav></header>`}
